namespace Microsoft.SemanticKernel.Connectors.AzureOpenAI;

/// <summary>
/// Azure OpenAI text-to-audio client for HTTP operations.
/// </summary>
[Experimental("SKEXP0001")]
internal sealed class AzureOpenAITextToAudioClient
{
    private readonly ILogger _logger;
    private readonly HttpClient _httpClient;

    private readonly string _deploymentName;
    private readonly string _endpoint;
    private readonly string _apiKey;
    private readonly string? _modelId;

    /// <summary>
    /// Supported voices for text-to-audio generation.
    /// </summary>
    private static readonly string[] s_supportedVoices = ["alloy", "echo", "fable", "onyx", "nova", "shimmer"];

    /// <summary>
    /// Supported response formats for text-to-audio generation.
    /// </summary>
    private static readonly string[] s_supportedFormats = ["mp3", "opus", "aac", "flac", "wav", "pcm"];

    /// <summary>
    /// Storage for AI service attributes.
    /// </summary>
    internal Dictionary<string, object?> Attributes { get; } = [];

    /// <summary>
    /// Creates an instance of the <see cref="AzureOpenAITextToAudioClient"/> with API key auth.
    /// </summary>
    /// <param name="deploymentName">Azure OpenAI deployment name, see https://learn.microsoft.com/azure/cognitive-services/openai/how-to/create-resource</param>
    /// <param name="endpoint">Azure OpenAI deployment URL, see https://learn.microsoft.com/azure/cognitive-services/openai/quickstart</param>
    /// <param name="apiKey">Azure OpenAI API key, see https://learn.microsoft.com/azure/cognitive-services/openai/quickstart</param>
    /// <param name="modelId">Azure OpenAI model id, see https://learn.microsoft.com/azure/cognitive-services/openai/how-to/create-resource</param>
    /// <param name="httpClient">Custom <see cref="HttpClient"/> for HTTP requests.</param>
    /// <param name="logger">The <see cref="ILogger"/> to use for logging. If null, no logging will be performed.</param>
    internal AzureOpenAITextToAudioClient(
        string deploymentName,
        string endpoint,
        string apiKey,
        string? modelId = null,
        HttpClient? httpClient = null,
        ILogger? logger = null)
    {
        Verify.NotNullOrWhiteSpace(deploymentName);
        Verify.NotNullOrWhiteSpace(endpoint);
        Verify.StartsWith(endpoint, "https://", "The Azure OpenAI endpoint must start with 'https://'");
        Verify.NotNullOrWhiteSpace(apiKey);

        this._deploymentName = deploymentName;
        this._endpoint = endpoint;
        this._apiKey = apiKey;
        this._modelId = modelId;

        this._httpClient = HttpClientProvider.GetHttpClient(httpClient);
        this._logger = logger ?? NullLogger.Instance;
    }

    internal async Task<IReadOnlyList<AudioContent>> GetAudioContentsAsync(
        string text,
        PromptExecutionSettings? executionSettings,
        CancellationToken cancellationToken)
    {
        Verify.NotNullOrWhiteSpace(text);

        AzureOpenAITextToAudioExecutionSettings audioExecutionSettings = AzureOpenAITextToAudioExecutionSettings.FromExecutionSettings(executionSettings)!;

        ValidateVoice(audioExecutionSettings.Voice);
        ValidateResponseFormat(audioExecutionSettings.ResponseFormat);

        var modelId = this.GetModelId(audioExecutionSettings);

        using var request = this.GetRequest(text, modelId, audioExecutionSettings);
        using var response = await this.SendRequestAsync(request, cancellationToken).ConfigureAwait(false);
        var data = await response.Content.ReadAsByteArrayAndTranslateExceptionAsync().ConfigureAwait(false);

        return [new(data, modelId)];
    }

    internal void AddAttribute(string key, string? value)
    {
        if (!string.IsNullOrEmpty(value))
        {
            this.Attributes.Add(key, value);
        }
    }

    #region private

    private static void ValidateVoice(string? voice)
    {
        if (string.IsNullOrWhiteSpace(voice) || !s_supportedVoices.Contains(voice!.ToLowerInvariant()))
        {
            throw new NotSupportedException($"The voice '{voice}' is not supported.");
        }
    }

    private static void ValidateResponseFormat(string? responseFormat)
    {
        if (string.IsNullOrWhiteSpace(responseFormat) || !s_supportedFormats.Contains(responseFormat!.ToLowerInvariant()))
        {
            throw new NotSupportedException($"The response format '{responseFormat}' is not supported.");
        }
    }

    private async Task<HttpResponseMessage> SendRequestAsync(
        HttpRequestMessage request,
        CancellationToken cancellationToken)
    {
        request.Headers.Add("User-Agent", HttpHeaderConstant.Values.UserAgent);
        request.Headers.Add("Api-Key", this._apiKey);
        request.Headers.Add(HttpHeaderConstant.Names.SemanticKernelVersion, HttpHeaderConstant.Values.GetAssemblyVersion(typeof(AzureOpenAITextToAudioClient)));

        try
        {
            return await this._httpClient.SendWithSuccessCheckAsync(request, cancellationToken).ConfigureAwait(false);
        }
        catch (HttpOperationException ex)
        {
            this._logger.LogError(
                "Error occurred on text-to-audio request execution: {ExceptionMessage}", ex.Message);

            throw;
        }
    }

    private HttpRequestMessage GetRequest(string text, string modelId, AzureOpenAITextToAudioExecutionSettings executionSettings)
    {
        const string DefaultApiVersion = "2024-02-15-preview";

        var baseUrl = !string.IsNullOrWhiteSpace(this._httpClient.BaseAddress?.AbsoluteUri) ?
            this._httpClient.BaseAddress!.AbsoluteUri :
            this._endpoint;

        var requestUrl = $"openai/deployments/{this._deploymentName}/audio/speech?api-version={DefaultApiVersion}";

        var payload = new AzureOpenAITextToAudioRequest(modelId, text, executionSettings.Voice)
        {
            ResponseFormat = executionSettings.ResponseFormat,
            Speed = executionSettings.Speed
        };

        return HttpRequest.CreatePostRequest($"{baseUrl.TrimEnd('/')}/{requestUrl}", payload);
    }

    private string GetModelId(AzureOpenAITextToAudioExecutionSettings executionSettings)
    {
        return
            !string.IsNullOrWhiteSpace(this._modelId) ? this._modelId! :
            !string.IsNullOrWhiteSpace(executionSettings.ModelId) ? executionSettings.ModelId! :
            this._deploymentName;
    }

    #endregion
}
